-- Extend the audited regular fixture with the existing playoff schema, LOCAL ONLY.
drop table playoff_picks,playoff_qb_picks,playoff_team_paths,playoff_games,playoff_rounds;
create table public.playoff_rounds(id bigint generated by default as identity primary key,season integer not null,round_key text not null,round_name text not null,round_order integer not null,status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(season,round_key),unique(season,round_order),check(status in('draft','open','locked','scored','finalized')));
create table public.playoff_games(id bigint generated by default as identity primary key,round_id bigint not null references public.playoff_rounds(id),external_game_id text unique,game_date timestamptz not null,home_team text not null,away_team text not null,home_score integer,away_score integer,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.playoff_picks(id bigint generated by default as identity primary key,user_id uuid references public.users(id),game_id bigint references public.playoff_games(id),picked_team text,predicted_spread integer,unique(user_id,game_id));
create table public.playoff_qb_picks(id bigint generated by default as identity primary key,user_id uuid references public.users(id),round_id bigint references public.playoff_rounds(id),qb_id uuid references public.qbs(id),unique(user_id,round_id));
create table public.playoff_team_paths(id bigint generated by default as identity primary key,user_id uuid references public.users(id),round_id bigint references public.playoff_rounds(id),team text,multiplier integer,continues_previous_path boolean,unique(user_id,round_id));
update settings set current_season=2099,current_week=1;
